[{"char_end":264,"char_start":253,"chunk_id":"dbebed791a25acf8a68dd882","clause_category":"Parties","document_id":"cuad_5dad919074219d103fb8","score":1.0,"section_hint":"Parties","text":"Distributor"},{"char_end":3920,"char_start":3895,"chunk_id":"ef298e0969ddf2761a6ab917","clause_category":"Document Name","document_id":"cuad_5dad919074219d103fb8","score":0.6231,"section_hint":"Document Name","text":"DISTRIBUTORSHIP AGREEMENT"},{"char_end":26760,"char_start":26271,"chunk_id":"cd83e57a844892c091e54def","clause_category":"License Grant","document_id":"cuad_5dad919074219d103fb8","score":0.5917,"section_hint":"License Grant","text":"Subject to the terms and conditions of this Agreement, Zogenix hereby appoints Distributor, and Distributor accepts appointment, as the exclusive distributor (even as to Zogenix) of the Product in the Field in the Territory during the Term, and grants to Distributor the exclusive rights to maintain Regulatory Approval of (while Distributor is the MAH Party), package, promote, market, offer for sale, sell, import and distribute the Product in the Field in the Territory during the Term."},{"char_end":67325,"char_start":66992,"chunk_id":"311a4580ff504d049cbbf73a","clause_category":"Exclusivity","document_id":"cuad_5dad919074219d103fb8","score":0.58,"section_hint":"Exclusivity","text":"Without limiting the foregoing, Distributor will have the exclusive right and responsibility in the Field in the Territory for the following:

(i) designing the Commercialization strategy and tactics for the Product, subject to JSC approval of the Commercialization Plan;

(ii) undertaking all promotional activities for the Product;"},{"char_end":26759,"char_start":26271,"chunk_id":"c89db34ba68e93836b0c444f","clause_category":"Exclusivity","document_id":"cuad_5dad919074219d103fb8","score":0.5735,"section_hint":"Exclusivity","text":"Subject to the terms and conditions of this Agreement, Zogenix hereby appoints Distributor, and Distributor accepts appointment, as the exclusive distributor (even as to Zogenix) of the Product in the Field in the Territory during the Term, and grants to Distributor the exclusive rights to maintain Regulatory Approval of (while Distributor is the MAH Party), package, promote, market, offer for sale, sell, import and distribute the Product in the Field in the Territory during the Term"},{"char_end":104203,"char_start":103534,"chunk_id":"ed33edd29f5004e01a505ff9","clause_category":"Affiliate License-Licensor","document_id":"cuad_5dad919074219d103fb8","score":0.5629,"section_hint":"Affiliate License-Licensor","text":"Distributor shall own the entire right, title and interest in and to any and all Inventions discovered, developed, identified, made, conceived or reduced to practice solely by Distributor or its Affiliates or Sub-distributors or its other subcontractors in the Territory and under or in connection with this Agreement, including in the course of conducting regulatory activities or Commercialization of the Product in the Field in the Territory, whether or not patented or patentable, together with any and all intellectual property rights in any such Inventions, including Patents that claim or disclose any such Inventions (collectively, the "Distributor Invention")."},{"char_end":28832,"char_start":28789,"chunk_id":"0c349a85f6bf59b7de1f0128","clause_category":null,"document_id":"cuad_5dad919074219d103fb8","score":0.5569,"section_hint":"unlabelled paragraph","text":"2.3 Supply of Product for Distributorship. "},{"char_end":66991,"char_start":66665,"chunk_id":"bd0c3e704515cbe53f71b92c","clause_category":"Exclusivity","document_id":"cuad_5dad919074219d103fb8","score":0.5559,"section_hint":"Exclusivity","text":"Distributor shall have the exclusive right to market, promote, sell, offer for sale, import, package and otherwise Commercialize the Product in the Field in the Territory, at its sole cost and expense, in accordance with Applicable Laws and the Commercialization Plan and subject to the terms and conditions of this Agreement."}]
